<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><title>Access Logs | A.T.O.M.</title><style>
:root{color-scheme:dark;font-family:Inter,system-ui,sans-serif;background:#080d16;color:#e8eef7;--line:#223044;--muted:#8392a8;--muted2:#607087;--lime:#b7f36b;--cyan:#62d9e8;--red:#ff7188}*{box-sizing:border-box}body{margin:0;min-width:320px;background:radial-gradient(ellipse at 78% -15%,rgba(46,105,130,.2),transparent 38%),#080d16}a{color:inherit;text-decoration:none}.app{min-height:100vh;display:grid;grid-template-columns:252px minmax(0,1fr)}.sidebar{position:sticky;top:0;height:100vh;padding:26px 17px 18px;display:flex;flex-direction:column;background:rgba(10,17,28,.96);border-right:1px solid var(--line)}.brand{display:flex;align-items:center;gap:12px;padding:0 9px 30px}.brand-mark{width:43px;height:43px;display:grid;place-items:center;border-radius:13px;background:linear-gradient(145deg,#d1ff8b,#86c94b);color:#101a20;font-size:20px;font-weight:950}.brand-name{font-size:15px;font-weight:850;letter-spacing:.17em}.brand-caption{margin-top:4px;color:var(--muted2);font-size:9px;letter-spacing:.19em}.side-label{padding:15px 11px 9px;color:#53647a;font-size:9px;font-weight:800;letter-spacing:.18em;text-transform:uppercase}.nav-link,.nav-soon{min-height:43px;display:flex;align-items:center;gap:12px;margin:3px 0;padding:0 12px;border-radius:10px;color:#91a0b5;font-size:12px}.nav-link.active{color:var(--lime);background:rgba(183,243,107,.1);border:1px solid rgba(183,243,107,.12)}.nav-icon{width:19px;text-align:center;font-size:15px}.nav-soon{color:#536176}.soon-tag{margin-left:auto;font-size:8px}.spacer{flex:1}.source{padding:14px;border:1px solid var(--line);border-radius:12px;background:#0d1724;color:var(--muted);font-size:9px}.source strong{display:block;color:var(--lime);margin:8px 0}main{min-width:0;padding:30px clamp(16px,3vw,44px)}header{display:flex;justify-content:space-between;gap:15px;align-items:flex-start;padding-bottom:22px;border-bottom:1px solid var(--line)}.eyebrow{color:var(--cyan);font-size:9px;letter-spacing:.18em;font-weight:800}h1{margin:8px 0 5px;font-size:clamp(25px,3vw,34px);letter-spacing:-.05em}.sub{color:var(--muted);font-size:11px}.live{padding:9px 12px;border:1px solid #3d5835;border-radius:8px;color:var(--lime);font-size:9px;font-weight:800}.section{display:flex;justify-content:space-between;gap:12px;margin:25px 0 12px;font-size:12px;font-weight:800}.hint{color:var(--muted);font-size:9px;font-weight:400}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px}.stat,.panel{padding:16px;border:1px solid var(--line);border-radius:12px;background:linear-gradient(145deg,#142131,#0d1623)}.stat label{color:#9baabd;font-size:10px}.num{margin-top:10px;font-size:26px;font-weight:800}.green{color:var(--lime)}.red{color:var(--red)}.panel{padding:0;overflow:hidden}.filters{display:flex;flex-wrap:wrap;gap:8px;padding:15px}.field,.btn{min-height:38px;padding:0 11px;border:1px solid #2a3b50;border-radius:8px;background:#0b1522;color:#e8eef7;font:11px Inter,system-ui}.search{width:min(310px,100%)}.btn{display:inline-flex;align-items:center;justify-content:center;background:#1b2b26;color:var(--lime);border-color:#3d5835;font-weight:800}.secondary{background:#142033;color:#aab8ca;border-color:#2a3b50}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}th{padding:12px;border-bottom:1px solid #2a394d;color:#718198;font-size:8px;letter-spacing:.12em;text-align:left}td{padding:13px 12px;border-bottom:1px solid #223044;color:#c8d3e1;font-size:10px}tbody tr:last-child td{border:0}.name{font-weight:750;color:#e5edf7}.muted{margin-top:4px;color:#718198;font-size:9px}.pill{display:inline-block;padding:5px 8px;border-radius:6px;background:#1b3024;color:var(--lime);font-size:8px;font-weight:850;text-transform:uppercase}.pill.denied{background:#351d29;color:var(--red)}.detail{color:var(--cyan);font-weight:750;font-size:9px}.empty{text-align:center;color:var(--muted);padding:25px}.pagination{display:flex;justify-content:space-between;align-items:center;padding:14px 15px;border-top:1px solid var(--line);color:var(--muted);font-size:9px}.pagination a{padding:8px;border:1px solid #2a3b50;border-radius:7px}.disabled{opacity:.35;pointer-events:none}footer{margin-top:22px;padding-top:13px;border-top:1px solid var(--line);color:#596a80;font-size:8px}@media(max-width:950px){.stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:820px){.app{grid-template-columns:66px minmax(0,1fr)}.sidebar{padding:20px 8px 14px}.brand{justify-content:center;padding:0 0 25px}.brand-copy,.side-label,.nav-text,.soon-tag,.source{display:none}.nav-link,.nav-soon{justify-content:center;padding:0}main{padding:24px 17px}}@media(max-width:560px){header{flex-direction:column}.filters .field,.filters .btn{flex:1}.search{width:100%}footer{line-height:1.7}}
</style></head><body><div class="app"><aside class="sidebar"><div class="brand"><div class="brand-mark">A.</div><div class="brand-copy"><div class="brand-name">A.T.O.M.</div><div class="brand-caption">BIOMETRIC ACCESS</div></div></div><div class="side-label">Workspace</div><a class="nav-link" href="{{ route('dashboard') }}"><span class="nav-icon">▦</span><span class="nav-text">Overview</span></a><a class="nav-link" href="{{ route('devices.index') }}"><span class="nav-icon">▣</span><span class="nav-text">Devices</span></a><a class="nav-link" href="{{ route('operators.index') }}"><span class="nav-icon">♙</span><span class="nav-text">Operators</span></a><a class="nav-link active" href="{{ route('access-logs.index') }}" aria-current="page"><span class="nav-icon">≡</span><span class="nav-text">Access logs</span></a><a class="nav-link" href="{{ route('sessions.index') }}"><span class="nav-icon">◷</span><span class="nav-text">Sessions</span></a><a class="nav-link" href="{{ route('mqtt-monitor.index') }}"><span class="nav-icon">⌁</span><span class="nav-text">MQTT monitor</span></a><div class="spacer"></div><div class="source">DATA SOURCE<strong>● Read-only connected</strong>atomic_access · monitoring only</div></aside><main>
<header><div><div class="eyebrow">BIOMETRIC ACCESS INTELLIGENCE / AUDIT TRAIL</div><h1>Access Logs</h1><div class="sub">Chronological history of fingerprint access attempts and decisions.</div></div><div class="live">● ACCESS AUDIT</div></header>
<div class="section">Access activity today <span class="hint">Event time · WIB</span></div><section class="stats"><article class="stat"><label>All recorded events</label><div class="num">{{ number_format($totalLogs) }}</div></article><article class="stat"><label>Today's attempts</label><div class="num">{{ number_format($todayLogs) }}</div></article><article class="stat"><label>Granted today</label><div class="num green">{{ number_format($todayGranted) }}</div></article><article class="stat"><label>Denied today</label><div class="num red">{{ number_format($todayDenied) }}</div></article></section>
<div class="section">Event history <span class="hint">{{ $logs->total() }} matching records · newest first</span></div><section class="panel"><form class="filters" method="GET" action="{{ route('access-logs.index') }}"><input class="field search" type="search" name="q" value="{{ $filters['q'] ?? '' }}" placeholder="Search operator, device, event ID, reason..."><select class="field" name="result"><option value="">All results</option><option value="granted" @selected(($filters['result'] ?? '') === 'granted')>Granted</option><option value="denied" @selected(($filters['result'] ?? '') === 'denied')>Denied</option></select><input class="field" type="date" name="start_date" value="{{ $filters['start_date'] ?? '' }}"><input class="field" type="date" name="end_date" value="{{ $filters['end_date'] ?? '' }}"><button class="btn">Filter</button><a class="btn secondary" href="{{ route('access-logs.index') }}">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Event time (WIB)</th><th>Operator</th><th>Device</th><th>Fingerprint</th><th>Result</th><th>Reason</th><th></th></tr></thead><tbody>
